/**
 ******************************************************************************
 * @file    charger_status.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Charger/gauge status-pin decoder — new PD5b module.
 *
 * Owner: Brendon Bone. Implements the decode rules for the BQ25170 STAT/PG
 * lines and the BQ34Z100 ALERT line (PA0/PB8/PB4 on the custom PCB), with a
 * timing-based detector for the BQ25170's 1 Hz fault blink. Pin meanings:
 * see charger_status.h.
 *
 * No task of its own: BrendonTask calls Charger_Tick about every 100 ms and
 * reads the result (battery_publish, usb_gate, the debug screen).
 *
 * One Charger_Tick, step by step:
 *   1. read STAT, PG and ALERT; a failed read -> UNKNOWN for this tick,
 *      latches kept
 *   2. VBUS high -> USB cable present; PG low -> input power good
 *   3. ALERT falling edge -> latched until Charger_ClearAlert
 *   4. STAT edges -> the 1 Hz blink detector (2 blink-like spacings = fault)
 *   5. decode: no input power, else fault blink, else STAT low = charging,
 *      STAT high = complete or disabled
 * Generative AI was used to assist in the refactoring process.
 ******************************************************************************
 */
#include "charger_status.h"

#include <stddef.h>

/* Open-drain semantics: the lines are pulled up and driven LOW when
 * asserted, so electrical 0 means "asserted" for STAT/PG/ALERT. */
#define CHARGER_LEVEL_LOW   0
#define CHARGER_LEVEL_HIGH  1

/**
 * @brief Feed one STAT sample into the blink detector.
 *
 * A fault is declared after CHARGER_BLINK_INTERVALS_REQ consecutive edge
 * spacings inside the 1 Hz tolerance window; a spacing outside the window
 * restarts the count, and a quiet line (no edge for CHARGER_BLINK_TIMEOUT_MS)
 * ends the blink so the steady-level decode takes over again.
 */
static void charger_blink_update(Charger_Monitor *mon, int stat_level,
                                 uint32_t now_ms)
{
    if (mon->stat_prev >= 0 && stat_level != (int)mon->stat_prev) {
        /* Edge observed. */
        if (mon->have_edge_time == 1U) {
            const uint32_t interval = (uint32_t)(now_ms - mon->last_edge_ms);

            if (interval >= CHARGER_BLINK_HALF_MIN_MS &&
                interval <= CHARGER_BLINK_HALF_MAX_MS) {
                if (mon->good_intervals < 255U) {
                    mon->good_intervals++;
                }
            } else {
                /* Spacing not blink-like: restart the streak. */
                mon->good_intervals = 0U;
            }
        }
        mon->last_edge_ms   = now_ms;
        mon->have_edge_time = 1U;
    } else if (mon->have_edge_time == 1U &&
               (uint32_t)(now_ms - mon->last_edge_ms) > CHARGER_BLINK_TIMEOUT_MS) {
        /* Line has been steady for longer than a blink half-period allows. */
        mon->good_intervals = 0U;
        mon->blink_active   = 0U;
    }

    if (mon->good_intervals >= CHARGER_BLINK_INTERVALS_REQ) {
        mon->blink_active = 1U;
    }

    mon->stat_prev = (int8_t)stat_level;
}

/**
 * @brief Latch a gauge alert on the ALERT falling edge (or an initial LOW).
 *
 * The latch survives the line returning HIGH — ALERT only means "read the
 * gauge registers", so it stays pending until the consumer clears it.
 */
static void charger_alert_update(Charger_Monitor *mon, int alert_level)
{
    const uint8_t first_sample = (mon->alert_prev < 0) ? 1U : 0U;

    if (alert_level == CHARGER_LEVEL_LOW &&
        (first_sample == 1U || mon->alert_prev == CHARGER_LEVEL_HIGH)) {
        mon->alert_pending = 1U;
    }

    mon->alert_prev = (int8_t)alert_level;
}

/**
 * @brief Combine PG, STAT level and the blink detector into one state.
 *
 * Priority: no input power trumps everything (the charger cannot be charging
 * or faulting into a pack with no VIN); an active fault blink trumps the
 * steady-level decode.
 */
static Charger_State charger_decode(const Charger_Monitor *mon, int stat_level)
{
    if (mon->pg_good == 0U) {
        return CHARGER_STATE_NO_INPUT;
    }
    if (mon->blink_active == 1U) {
        return CHARGER_STATE_FAULT;
    }
    if (stat_level == CHARGER_LEVEL_LOW) {
        return CHARGER_STATE_CHARGING;
    }
    return CHARGER_STATE_COMPLETE_OR_DISABLED;
}

/**
 * @brief Initialise the monitor with injected pin readers.
 */
Charger_Status Charger_Init(Charger_Monitor *mon, const Charger_Pins *pins)
{
    if (mon == NULL || pins == NULL ||
        pins->read_stat == NULL || pins->read_pg == NULL ||
        pins->read_alert == NULL) {
        return CHARGER_ERR_PARAM;
    }

    mon->pins           = pins;
    mon->state          = CHARGER_STATE_UNKNOWN;
    mon->pg_good        = 0U;
    mon->vbus_present   = 0U;
    mon->stat_prev      = -1;
    mon->have_edge_time = 0U;
    mon->last_edge_ms   = 0U;
    mon->good_intervals = 0U;
    mon->blink_active   = 0U;
    mon->alert_prev     = -1;
    mon->alert_pending  = 0U;

    return CHARGER_OK;
}

/**
 * @brief Sample all pins and update the decoded state (see header).
 */
Charger_Status Charger_Tick(Charger_Monitor *mon, uint32_t now_ms)
{
    int stat_level, pg_level, alert_level;

    if (mon == NULL || mon->pins == NULL) {
        return CHARGER_ERR_PARAM;
    }

    stat_level  = mon->pins->read_stat(mon->pins->ctx);
    pg_level    = mon->pins->read_pg(mon->pins->ctx);
    alert_level = mon->pins->read_alert(mon->pins->ctx);

    if (stat_level < 0 || pg_level < 0 || alert_level < 0) {
        /* A reader failed: degrade to UNKNOWN for this tick but keep the
         * ALERT latch and blink history — a transient read fault should not
         * silently discard a pending gauge alert. */
        mon->state = CHARGER_STATE_UNKNOWN;
        return CHARGER_ERR_PIN;
    }

    /* VBUS is optional (the dev board routes PA9 to USB VBUS sensing). */
    if (mon->pins->read_vbus != NULL) {
        const int vbus_level = mon->pins->read_vbus(mon->pins->ctx);
        mon->vbus_present = (vbus_level == CHARGER_LEVEL_HIGH) ? 1U : 0U;
    } else {
        mon->vbus_present = 0U;
    }

    /* Open-drain PG: LOW = valid input power present. */
    mon->pg_good = (pg_level == CHARGER_LEVEL_LOW) ? 1U : 0U;

    charger_alert_update(mon, alert_level);
    charger_blink_update(mon, stat_level, now_ms);

    mon->state = charger_decode(mon, stat_level);

    return CHARGER_OK;
}

/**
 * @brief Decoded charger state from the last successful tick.
 */
Charger_State Charger_GetState(const Charger_Monitor *mon)
{
    return (mon == NULL) ? CHARGER_STATE_UNKNOWN : mon->state;
}

/**
 * @brief 1 while PG reports valid input power.
 */
uint8_t Charger_IsPowerGood(const Charger_Monitor *mon)
{
    return (mon != NULL && mon->pg_good == 1U) ? 1U : 0U;
}

/**
 * @brief 1 while VBUS is high (charger powered from USB).
 */
uint8_t Charger_IsVbusPresent(const Charger_Monitor *mon)
{
    return (mon != NULL && mon->vbus_present == 1U) ? 1U : 0U;
}

/**
 * @brief 1 while the STAT 1 Hz fault blink is being observed.
 */
uint8_t Charger_IsFaultBlinkActive(const Charger_Monitor *mon)
{
    return (mon != NULL && mon->blink_active == 1U) ? 1U : 0U;
}

/**
 * @brief 1 if a gauge alert has been latched since the last clear.
 */
uint8_t Charger_AlertPending(const Charger_Monitor *mon)
{
    return (mon != NULL && mon->alert_pending == 1U) ? 1U : 0U;
}

/**
 * @brief Acknowledge and clear a pending gauge alert.
 */
void Charger_ClearAlert(Charger_Monitor *mon)
{
    if (mon != NULL) {
        mon->alert_pending = 0U;
    }
}
